// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("VotingStatus");

  // Voting Summary state
  const [votingSummary, setVotingSummary] = useState({ totalVoted: 0, students: [] });

  // Reports tab states
  const [reportElection, setReportElection] = useState(null);
  const [reportPosition, setReportPosition] = useState("");
  const [filteredResults, setFilteredResults] = useState({});

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchVotingState = async () => { try { const res = await api.get("/admin/voting-state"); setVotingOpen(res.data.votingOpen); } catch (err) { handleApiError(err); } };
  const fetchPendingUsers = async () => { try { const res = await api.get("/admin/pending-users"); setPendingUsers(res.data); } catch (err) { handleApiError(err); } };

  // 🔹 Updated fetchCandidates to support electionId
  const fetchCandidates = async (electionId = selectedElection) => {
    if (!electionId) return;
    try {
      const res = await api.get("/admin/candidates", { params: { electionId } });
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => { try { const res = await api.get("/admin/logs"); setLogs(res.data); } catch (err) { handleApiError(err); } };
  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);
      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        setReportElection(firstElection.id);
        fetchResults(firstElection.id);
        fetchCandidates(firstElection.id); // 🔹 fetch candidates for the first election
      }
    } catch (err) { handleApiError(err); }
  };
  const fetchResults = async (electionId) => { try { const res = await api.get("/admin/results", { params: { electionId } }); setResults(res.data.positionResults || {}); setWinners(res.data.winners || {}); setFilteredResults(res.data.positionResults || {}); } catch (err) { handleApiError(err); } };
  const fetchVotingSummary = async () => { try { const res = await api.get("/admin/voting-summary"); setVotingSummary(res.data); } catch (err) { handleApiError(err); } };

  const toggleVoting = async () => { try { const res = await api.post("/admin/toggle-voting"); setVotingOpen(res.data.votingOpen); setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`); } catch (err) { handleApiError(err); } };
  const approveUser = async (id) => { try { await api.post(`/admin/approve-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const rejectUser = async (id) => { try { await api.post(`/admin/reject-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const approveCandidate = async (id) => { try { await api.post(`/admin/approve-candidate/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const deleteCandidate = async (id) => { if (!window.confirm("Delete this candidate?")) return; try { await api.delete(`/admin/candidates/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const generateReport = async () => { try { const res = await api.post("/admin/generate-report"); setReportHash(res.data.hash); } catch (err) { handleApiError(err); } };

  // 🔹 Election change updates candidates
  const handleElectionChange = (id) => {
    const election = elections.find((el) => el.id === id);
    setSelectedElection(id);
    setSelectedElectionVotingOpen(election?.votingOpen ?? false);
    setReportElection(id);

    fetchResults(id);
    fetchCandidates(id); // 🔹 fetch candidates for selected election
  };

  // ---------------- Reports Functions ----------------
  const applyReportFilters = () => {
    let filtered = { ...results };
    if (reportPosition) {
      filtered = { [reportPosition]: filtered[reportPosition] || [] };
    }
    setFilteredResults(filtered);
  };

  const resetReportFilters = () => {
    setReportElection(selectedElection);
    setReportPosition("");
    setFilteredResults(results);
  };

  const exportExcel = () => { console.log("Export Excel:", filteredResults); alert("Export Excel functionality triggered"); };
  const exportPDF = () => { console.log("Export PDF:", filteredResults); alert("Export PDF functionality triggered"); };
  const printReport = () => { window.print(); };

  useEffect(() => {
    if (!token) { navigate("/login"); return; }
    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchElections();
      await fetchVotingSummary();
    };
    init();
  }, [token]);

  // ---------------- Candidate Actions ----------------
  const rejectCandidateWithComment = async (id) => {
    let comment = "";
    while (!comment) {
      comment = prompt("Enter the rejection reason for the student (required):");
      if (comment === null) return; // Cancel pressed
      if (!comment.trim()) alert("Comment cannot be empty.");
    }

    if (!window.confirm("Reject this candidate with the entered comment?")) return;

    try {
      await api.post(`/admin/reject-candidate/${id}`, { comment });
      fetchCandidates();
      setMessage("Candidate rejected with comment.");
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Rendered Sections ----------------
  const renderContent = () => {
    switch (activeTab) {
      case "VotingStatus":
        return (
          <Card title="Voting Status">
            <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>{votingOpen ? "Open" : "Closed"}</p>
            <button onClick={toggleVoting} style={{ marginTop: "10px", padding: "10px 20px", borderRadius: "8px", border: "none", backgroundColor: votingOpen ? "#dc3545" : "#28a745", color: "#fff", cursor: "pointer", fontWeight: "bold" }}>{votingOpen ? "Close Voting" : "Open Voting"}</button>
          </Card>
        );
      case "VotingSummary":
        return (
          <Card title="Voting Summary">
            <h3>Total Students Voted: {votingSummary.totalVoted}</h3>
            <table style={{ width: "100%", borderCollapse: "collapse", marginTop: "15px" }}>
              <thead>
                <tr style={{ background: "#f1f1f1" }}>
                  <th style={{ padding: "8px", textAlign: "left" }}>Student Number</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Status</th>
                </tr>
              </thead>
              <tbody>
                {votingSummary.students.length > 0 ? votingSummary.students.map((s, i) => (
                  <tr key={i} style={{ borderTop: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{s.studentNumber}</td>
                    <td style={{ padding: "8px" }}>{s.name}</td>
                    <td style={{ padding: "8px", fontWeight: "bold", color: "green" }}>{s.status}</td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan="3" style={{ padding: "10px", textAlign: "center", color: "#777" }}>No students have voted yet.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </Card>
        );
      case "PendingUsers":
        return (
          <Card title="Pending Voter Registrations">
            {pendingUsers.length === 0 ? <p style={{ color: "#777", fontStyle: "italic" }}>No pending users.</p> :
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Student #</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Email</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingUsers.map(u => (
                    <tr key={u.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{u.studentNumber}</td>
                      <td style={{ padding: "8px" }}>{u.name}</td>
                      <td style={{ padding: "8px" }}>{u.email}</td>
                      <td style={{ padding: "8px", textAlign: "center" }}>
                        <button onClick={() => approveUser(u.id)} style={{ marginRight: "5px", background: "#28a745", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Approve</button>
                        <button onClick={() => rejectUser(u.id)} style={{ background: "#dc3545", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Reject</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>}
          </Card>
        );
      case "Candidates":
        return (
          <Card title="Candidates">
            {/* 🔹 Election selector for candidates */}
            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="candidatesElection" style={{ fontWeight: "bold", marginRight: "5px" }}>Election:</label>
              <select
                id="candidatesElection"
                value={selectedElection || ""}
                onChange={(e) => handleElectionChange(parseInt(e.target.value))}
                style={{ padding: "5px 10px", borderRadius: "6px" }}
              >
                {elections.map(el => {
                  const start = el.startsAt ? new Date(el.startsAt).toLocaleDateString() : "N/A";
                  const end = el.endsAt ? new Date(el.endsAt).toLocaleDateString() : "Closed";
                  return <option key={el.id} value={el.id}>{el.name} ({start} - {end})</option>;
                })}
              </select>
            </div>

            {candidates.length === 0 ? (
              <p style={{ color: "#777", fontStyle: "italic" }}>No candidates registered for this election.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Position</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Party</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Forms</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Status</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {candidates.map(c => (
                    <tr
                      key={c.id}
                      style={{
                        borderTop: "1px solid #eee",
                        backgroundColor: c.approved
                          ? "#e6ffe6"
                          : (!c.documents || c.documents.length === 0)
                          ? "#ffe6e6"
                          : "#fff",
                      }}
                    >
                      <td style={{ padding: "8px" }}>{c.user?.name}</td>
                      <td style={{ padding: "8px" }}>{c.position}</td>
                      <td style={{ padding: "8px" }}>{c.party || "N/A"}</td>
                      <td style={{ padding: "8px" }}>
                        {c.documents?.map((d, i) => <a key={i} href={d} target="_blank" rel="noreferrer">Form {i+1}</a>)}
                      </td>
                      <td style={{ padding: "8px", textAlign: "center", fontWeight: "bold", color: c.approved ? "green" : "red" }}>
                        {c.approved ? "Approved" : "Pending"}
                      </td>
                      <td style={{ padding: "8px", textAlign: "center" }}>
                        {!c.approved && <button onClick={() => approveCandidate(c.id)} style={{ marginRight: "5px", background: "#28a745", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Approve</button>}
                        {!c.approved && <button onClick={() => rejectCandidateWithComment(c.id)} style={{ background: "#dc3545", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Reject</button>}
                        {c.approved && <button onClick={() => deleteCandidate(c.id)} style={{ background: "#dc3545", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Delete</button>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );
      case "Reports":
        return (
          <Card title="Reports">
            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="reportElection" style={{ fontWeight: "bold", marginRight: "5px" }}>Election:</label>
              <select id="reportElection" value={reportElection || ""} onChange={(e) => setReportElection(parseInt(e.target.value))} style={{ padding: "5px 10px", borderRadius: "6px", marginRight: "10px" }}>
                {elections.map(el => <option key={el.id} value={el.id}>{el.name}</option>)}
              </select>
              <label htmlFor="reportPosition" style={{ fontWeight: "bold", marginRight: "5px" }}>Position:</label>
              <input id="reportPosition" value={reportPosition} onChange={(e) => setReportPosition(e.target.value)} placeholder="Position filter" style={{ padding: "5px 10px", borderRadius: "6px", marginRight: "10px" }} />
              <button onClick={applyReportFilters} style={{ marginRight: "5px", padding: "5px 10px", borderRadius: "6px", cursor: "pointer" }}>Apply</button>
              <button onClick={resetReportFilters} style={{ padding: "5px 10px", borderRadius: "6px", cursor: "pointer" }}>Reset</button>
            </div>
            <div style={{ marginBottom: "15px" }}>
              <button onClick={exportExcel} style={{ marginRight: "5px", padding: "5px 10px", borderRadius: "6px", cursor: "pointer" }}>Export Excel</button>
              <button onClick={exportPDF} style={{ marginRight: "5px", padding: "5px 10px", borderRadius: "6px", cursor: "pointer" }}>Export PDF</button>
              <button onClick={printReport} style={{ padding: "5px 10px", borderRadius: "6px", cursor: "pointer" }}>Print</button>
            </div>
            <pre>{JSON.stringify(filteredResults, null, 2)}</pre>
          </Card>
        );
      default:
        return <p>Select a tab</p>;
    }
  };

  return (
    <div className="dashboard-container" style={{ display: "flex", minHeight: "100vh", fontFamily: "Arial, sans-serif", backgroundColor: "#f4f6f8" }}>
      <div className="sidebar" style={{ background: "#343a40", color: "#fff", paddingTop: "20px", display: "flex", flexDirection: "column", width: sidebarOpen ? "220px" : "60px", transition: "width 0.3s" }}>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ background: "none", border: "none", color: "#fff", padding: "10px", cursor: "pointer", fontSize: "18px" }}>{sidebarOpen ? "«" : "»"}</button>
        {["VotingStatus","VotingSummary","PendingUsers","Candidates","Reports"].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} style={{ background: activeTab === tab ? "#007bff" : "transparent", border: "none", color: "#fff", padding: "10px", textAlign: "left", cursor: "pointer" }}>{tab}</button>
        ))}
      </div>
      <div className="content" style={{ flex: 1, padding: "20px" }}>
        {message && <p style={{ background: "#ffecb3", padding: "10px", borderRadius: "6px", marginBottom: "15px" }}>{message}</p>}
        {renderContent()}
      </div>
    </div>
  );
}
